/* Sidebar Mercantil — degradado azul institucional, portado de Sidebar.svelte / Sidebar.tsx */
* { box-sizing: border-box; }
html, body {
  margin: 0;
  height: 100%;
  min-height: 100vh;
  font-family: 'Poppins', 'Helvetica Neue', Arial, sans-serif;
}

.mc-sidebar {
  display: flex;
  flex-direction: column;
  height: 100%;
  min-height: 100vh;
  background: linear-gradient(180deg, #1E5FA8 0%, #14327D 70%, #0D2559 100%);
  color: #fff;
  overflow-y: auto;
}

.mc-sidebar__logo {
  padding: 20px 22px 15px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.mc-sidebar__brand {
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: #fff;
}

.mc-sidebar__brand-sub {
  margin-top: 2px;
  font-size: 11.5px;
  color: rgba(255,255,255,0.65);
}

.mc-sidebar__section-label {
  padding: 14px 14px 6px 22px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.45);
}

.mc-sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0 14px;
  flex: 1;
}

.mc-nav-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 11px 14px;
  border-radius: 9px;
  border-left: 3px solid transparent;
  font-size: 14px;
  font-weight: 500;
  color: rgba(255,255,255,0.75);
  cursor: pointer;
  background: none;
  border-top: none;
  border-right: none;
  border-bottom: none;
  width: 100%;
  text-align: left;
  transition: background-color 0.15s, color 0.15s;
  user-select: none;
}

.mc-nav-item:hover {
  background: rgba(255,255,255,0.1);
  color: #fff;
}

.mc-nav-item.active {
  background: rgba(255,255,255,0.15);
  color: #fff;
  font-weight: 600;
  border-left-color: #FFBE00;
}

.mc-nav-item.disabled {
  color: rgba(255,255,255,0.35);
  cursor: not-allowed;
}
.mc-nav-item.disabled:hover {
  background: none;
  color: rgba(255,255,255,0.35);
}

.mc-nav-item__label {
  display: flex;
  align-items: center;
  gap: 12px;
}

.mc-nav-item__badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 20px;
  height: 20px;
  padding: 0 6px;
  border-radius: 999px;
  background: #D6202A;
  font-size: 10.5px;
  font-weight: 700;
  color: #fff;
}

.mc-sidebar__footer {
  margin-top: auto;
  padding: 10px 14px 16px;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.mc-sidebar__logout {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 11px 14px;
  border: none;
  border-radius: 9px;
  background: none;
  color: rgba(255,255,255,0.85);
  font-size: 12.5px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background-color 0.15s;
}

.mc-sidebar__logout:hover {
  background: rgba(255,255,255,0.12);
}

